// Issue catalog (Semrush-style errors / warnings / notices) and the rules that raise them.
// Page rules run per crawled page; site rules run once the crawl is complete.
import { isArticle } from "./conversion.mjs";
import { schemaPageIssues } from "./schema.mjs";
import { videoNotMain } from "./video-checks.mjs";

export const CHECKS = {
  // ---------------- Errors ----------------
  http_4xx: ["error", "4XX status code", "Visitors and crawlers hit a dead end; link equity pointing here is wasted.", "Restore the page, or 301-redirect it to the closest live page and update internal links."],
  http_5xx: ["error", "5XX server error", "The server failed to return the page; repeated errors can drop pages from the index.", "Check server logs and hosting limits; fix the failing script or resource."],
  broken_internal_link: ["error", "Broken internal links", "Links to pages that return 4XX/5XX hurt UX and waste crawl budget.", "Update or remove the link, or redirect the target."],
  broken_internal_image: ["error", "Broken internal images", "Missing images look broken and lose image-search traffic.", "Fix the image path or upload the missing file."],
  missing_title: ["error", "Missing title tag", "The title is the main signal for what a page is about and the headline in search results.", "Add a unique, descriptive <title> (about 50–60 characters)."],
  dup_title: ["error", "Duplicate title tags", "Search engines can't tell which page to rank; results look identical.", "Give every indexable page a unique title."],
  dup_description: ["error", "Duplicate meta descriptions", "Identical snippets reduce click-through and signal duplicate pages.", "Write a unique description per page."],
  dup_content: ["error", "Duplicate content", "Pages with the same main text compete with each other.", "Merge the pages, make them distinct, or set a canonical."],
  redirect_chain: ["error", "Redirect chains and loops", "Each hop slows the page and loops make it unreachable.", "Redirect straight to the final URL and update links to point at it."],
  canonical_broken: ["error", "Canonical points to a broken or redirected URL", "The preferred version can't be indexed.", "Point the canonical at a live 200 page (usually the page itself)."],
  canonical_multiple: ["error", "Multiple canonical tags", "Conflicting canonicals may be ignored altogether.", "Keep exactly one rel=canonical."],
  invalid_jsonld: ["error", "Invalid structured data (JSON-LD)", "Unparseable markup is ignored, so rich results are lost.", "Fix the JSON syntax (validate with Google's Rich Results Test)."],
  mixed_content: ["error", "Mixed content (HTTP resources on HTTPS)", "Browsers block or warn about insecure resources.", "Load every script, style and image over HTTPS."],
  sitemap_bad_url: ["error", "Sitemap contains non-200 or non-indexable URLs", "Sitemaps should list only pages you want indexed.", "Remove redirected, broken or noindex URLs from the sitemap."],
  http_page: ["error", "Page served over HTTP", "Insecure pages lose trust signals and show 'Not secure'.", "Serve the site over HTTPS and 301-redirect HTTP."],
  very_slow: ["error", "Very slow server response (over 5 s)", "Users leave and crawlers fetch fewer pages.", "Check hosting, caching and heavy server-side code."],

  // ---------------- Warnings ----------------
  missing_description: ["warning", "Missing meta description", "Search engines write their own snippet, often a poor one.", "Add a 120–160 character description that sells the click."],
  missing_h1: ["warning", "Missing H1 heading", "The H1 tells users and crawlers the page topic.", "Add one descriptive H1."],
  img_missing_alt: ["warning", "Images without alt text", "Alt text helps accessibility and image search.", "Describe each meaningful image in its alt attribute."],
  temporary_redirect: ["warning", "Temporary redirects (302/307)", "Google keeps showing the old URL and doesn't take the target as canonical (no PageRank is lost: it's a canonical signal).", "For a permanent move use 301/308; keep 302/307 only for genuinely temporary detours."],
  sitemap_not_in_robots: ["notice", "Sitemap not declared in robots.txt", "Declaring it helps every search and AI crawler find the sitemap.", "Add a line: Sitemap: https://your-site/sitemap.xml"],
  external_link_blocked: ["notice", "External link refused the checker (401/403/429)", "The site blocks automated checks; the link usually works in a browser.", "Open the link manually to confirm it still works."],
  broken_external_link: ["warning", "Broken external links", "Dead outbound links look neglected.", "Update or remove the link."],
  slow_page: ["warning", "Slow server response (over 1.5 s)", "Slow pages hurt users and Core Web Vitals.", "Enable caching/compression and reduce server work."],
  large_html: ["warning", "Large HTML (over 2 MB uncompressed)", "When crawling for Google Search, Googlebot reads only the first 2 MB of an HTML file (64 MB for a PDF) and ignores the rest, so text, links and structured data past that point aren't indexed (Googlebot docs, file size limits clarified 3 Feb 2026). The limit is on the uncompressed HTML; images, CSS and JS files are fetched separately. Heavy pages also load slowly on mobile.", "Bring the HTML under 2 MB: move inline scripts, styles, SVG sprites, base64 images and embedded JSON data into separate files, and paginate very long lists. Keep the main content, canonical and structured data near the top."],
  missing_viewport: ["warning", "Missing viewport meta tag", "Without it, mobile browsers render a desktop layout.", "Add <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">."],
  noindex_in_sitemap: ["warning", "Noindex page listed in sitemap", "Conflicting signals: the sitemap asks to index a noindex page.", "Remove it from the sitemap or allow indexing."],
  sitemap_orphan: ["notice", "Orphan pages (in sitemap, no internal links)", "Pages with no internal links are hard to discover and rank.", "Link to them from related pages and navigation."],
  missing_lang: ["warning", "Missing lang attribute", "The page language helps search engines and screen readers.", "Add <html lang=\"en\"> (or the right language)."],
  hreflang_issue: ["warning", "Hreflang issues", "Wrong hreflang can show the wrong language version.", "Use valid language codes and absolute URLs, include a self-reference."],

  // ---------------- Notices ----------------
  noindex_page: ["notice", "Pages blocked from indexing (noindex)", "These pages won't appear in search. Fine if intended.", "Remove noindex from pages you want found."],
  blocked_by_robots: ["notice", "Pages blocked by robots.txt", "Crawlers can't fetch these URLs.", "Allow them in robots.txt if they should rank."],
  permanent_redirect: ["notice", "Permanent redirects (301/308)", "Fine on their own, but internal links should point to the final URL.", "Update internal links to the destination."],
  deep_page: ["notice", "Pages more than 3 clicks from the homepage", "Deep pages get crawled less and look less important.", "Link to them from higher-level pages."],
  single_inlink: ["notice", "Pages with only one incoming internal link", "Weakly linked pages are easy to miss.", "Add contextual links from related pages."],
  nofollow_internal: ["notice", "Nofollow on internal links", "You're telling crawlers not to follow your own pages.", "Remove rel=nofollow from internal links."],
  missing_canonical: ["notice", "No canonical tag", "A self-referencing canonical guards against duplicate URLs (parameters, tracking tags).", "Add <link rel=\"canonical\"> pointing to the page itself."],
  canonical_elsewhere: ["notice", "Canonical points to another page", "This page asks not to be indexed in its own right. Fine if intended.", "Check that the canonical target is the right version."],
  not_in_sitemap: ["notice", "Indexable pages missing from the sitemap", "Sitemaps help discovery of every page you want indexed.", "Add them to the XML sitemap."],
  missing_og: ["notice", "Missing Open Graph tags", "Shared links show a poor preview on social media and chat apps.", "Add og:title, og:description and og:image."],
  missing_jsonld: ["notice", "No structured data", "Structured data helps Google understand the page and is required for rich results (only some types still earn one: see Google's search gallery). It is not a ranking factor on its own.", "Add JSON-LD in the server HTML for what the page really is: Organization or LocalBusiness on the home page, Article/BlogPosting, Product, BreadcrumbList, VideoObject. FAQ and HowTo no longer earn rich results (FAQ stopped 7 May 2026, HowTo 2023)."],
  many_links: ["notice", "Too many on-page links (over 300)", "Link equity is spread thin and the page is hard to use.", "Trim navigation and repeated links."],
  external_nofollow_all: ["notice", "All external links are nofollow", "Normal editorial links don't need nofollow.", "Use nofollow only for paid/untrusted links (sponsored/ugc)."],
  no_robots_txt: ["notice", "robots.txt not found", "Crawlers expect /robots.txt; it is also where you point to your sitemap.", "Add a robots.txt with a Sitemap: line."],
  no_sitemap: ["notice", "No XML sitemap found", "Sitemaps speed up discovery of new and deep pages.", "Create /sitemap.xml and reference it in robots.txt."],
  no_llms_txt: ["notice", "No llms.txt", "Optional: some AI tools read /llms.txt. Google says Google Search doesn't use it (AI optimisation guide).", "Only if you want: a short, accurate llms.txt summarising key pages. Not a ranking or citation lever."],
  schema_faq_hidden: ["notice", "FAQ markup for questions not shown on the page", "Google's structured data policies require markup to describe visible content; hidden FAQ markup can lose rich results or earn a manual action.", "Show every marked-up question and answer on the page, or remove them from the FAQPage markup."],
  schema_breadcrumb_hidden: ["notice", "Breadcrumb markup without a visible breadcrumb trail", "Markup should describe content readers can see.", "Add a visible Home › … trail matching the BreadcrumbList, or drop the markup."],
  schema_self_review: ["notice", "Rating or review markup on the business's own entity", "Google ignores self-serving review markup for LocalBusiness and Organization on their own site and may treat it as spam.", "Remove aggregateRating/review from your own business markup; show real reviews as plain content instead."],
  near_duplicate: ["notice", "Near-duplicate page (shares most of its text with another page)", "Pages that differ only by a swapped place or keyword match Google's doorway and scaled-content spam patterns, and near-duplicates get clustered so only one is shown.", "Give each page facts that are only true for it, or merge the pages. Compare with: node src/cli.mjs similar <project>."],
  no_conversion_path: ["notice", "No way to act on the page", "Visitors who are ready can't take the next step here: no phone or email link, form or call-to-action button.", "Add the action that fits the page: a phone link, a short form, or a button to book, buy, sign up or get a quote."],
  article_no_money_link: ["notice", "Article doesn't link to a money page", "Articles earn most of a site's links and readers; with no link from the text to a service, product or pricing page, neither reaches the pages that convert.", "Add a link in the text to the page that solves the reader's problem (service, product, feature or pricing), with a descriptive anchor."],
  sitemap_lastmod_uniform: ["notice", "Most sitemap URLs share one lastmod date", "Google and Bing use lastmod only when it is consistently accurate; a bulk date looks like a site-wide reset.", "Set each URL's lastmod to the date its content last really changed."],

  // ---------------- Information: not Google ranking issues (REQ-044, Oct 2026) ----------------
  // Kept visible so nothing is hidden, as notices: they don't count toward Site Health. The numbers are this tool's
  // conventions, not Google limits.
  title_too_long: ["notice", "Title over 65 characters (information: not a Google ranking issue)", "Google sets no length limit for the <title> and doesn't rank shorter titles higher. It truncates title links to fit the device width, so the end of a long title may be cut off in results (title links doc). 65 characters is this tool's rough estimate of where a cut can start.", "Nothing to fix for ranking. If the words that matter most come late, move them to the front so they survive a cut."],
  title_too_short: ["notice", "Title under 20 characters (information: not a Google ranking issue)", "Google sets no minimum title length. A very short title may not describe the page, and Google can then show a title link built from the page's headings or other text instead (title links doc).", "If the title doesn't say what the page is, make it descriptive and concise. A short, accurate title is fine."],
  desc_length: ["notice", "Meta description short or long (information: not a Google ranking issue)", "The meta description isn't a Google ranking factor and has no length limit; Google truncates snippets to fit the device width and often writes its own snippet from the page text to match the search (snippets doc). The 70–170 character range is this tool's convention.", "Nothing to fix for ranking. If you want a say in the snippet, write a description that accurately summarises the page."],
  multiple_h1: ["notice", "Several H1 headings (information: not a Google issue)", "Google says several H1 elements on a page are fine: it uses headings to understand the page and doesn't count H1s (John Mueller, 2017 and 2019). A clear heading outline still helps readers and screen readers.", "Nothing to fix for Google. Keep headings meaningful and in a sensible order."],
  low_word_count: ["notice", "Under 200 words (information: not a Google ranking issue)", "Google has no minimum word count and says word count isn't a ranking factor (John Mueller); short pages such as contact or booking pages can do their job well. Pages that add nothing useful still struggle, whatever their length.", "Check the page gives visitors what they came for. Add detail only where it helps them; don't pad."],
  low_text_ratio: ["notice", "Low text-to-HTML ratio, under 10% (information: not a Google metric)", "Google doesn't use a text-to-HTML ratio. Very heavy markup can slow a page, and little visible text can mean a thin page, so it's a hint to look, nothing more.", "Only if the page is slow or thin: remove unneeded markup or add useful content."],
  url_too_long: ["notice", "URL over 115 characters (information: not a Google ranking issue)", "Google doesn't rank by URL length. Google recommends simple, readable URLs; long ones are harder to read and share.", "Nothing to fix for ranking. For new pages, prefer short, readable URLs; don't change working URLs just for length."],
  dup_title_h1: ["notice", "Title and H1 identical (information: not a Google issue)", "Google doesn't penalise a title that matches the H1; both describing the page the same way is normal. Varying them is optional.", "Nothing to fix. Optionally use the H1 or the title for a second phrasing readers use."],

  // ---------------- Content age, structure and video ----------------
  content_stale: ["notice", "Article not updated in over 12 months", "The newest date this article states is more than a year before the audit. Facts, prices, laws and screenshots go out of date, and readers and AI answers prefer current information. Age alone is not a ranking penalty.", "Review the article: correct what changed, add what's new, then update the visible date and dateModified. Don't change the date without changing the content."],
  title_past_year: ["notice", "Title or H1 mentions a past year", "A past year in the headline (\"… 2024\") makes the page look out of date in search results and lowers clicks.", "If the content is current, update the year or remove it; if the page is about that year on purpose (history, a past event), ignore this notice."],
  heading_skip: ["notice", "Heading levels skipped", "Headings are the page's outline for screen readers and crawlers; jumping from H2 to H4 leaves a gap in it.", "Use the next level down for sub-sections (H2 → H3 → H4). Change the styling with CSS, not the heading level."],
  heading_before_h1: ["notice", "Headings before the H1", "The H1 should open the page's content; headings above it make the outline start with something else.", "Move the H1 above the other content headings, or turn the earlier ones into plain text if they are labels."],
  long_no_toc: ["notice", "Long page without jump links (table of contents)", "On a long page with many sections, links to each section help readers find their answer, and Google can show them as \"jump to\" links in results.", "Add a short contents list near the top linking to each H2 (give each H2 an id, link with href=\"#id\")."],
  long_paragraphs: ["notice", "Very long paragraphs (over 180 words)", "Walls of text are hard to read, especially on phones, and readers leave before reaching the answer.", "Split them into paragraphs of one idea each; use lists or sub-headings where they help."],
  video_no_schema: ["warning", "Video without VideoObject markup", "Google needs VideoObject structured data (or a clear video page) to show the video in video results and key moments.", "Add VideoObject JSON-LD for each main video with at least name, thumbnailUrl and uploadDate (also description, duration, embedUrl or contentUrl)."],
  video_schema_incomplete: ["warning", "VideoObject missing required fields", "Google requires name, thumbnailUrl and uploadDate; without them the video can't get video rich results.", "Fill in the missing fields with the video's real title, thumbnail image URL and upload date."],

  // ---------------- Crawlability (Google Search Central crawling docs) ----------------
  robots_txt_error: ["error", "robots.txt answers with a server error or not at all", "When robots.txt returns 5xx or times out, Google stops crawling the whole site until it can read it again.", "Make /robots.txt return 200 (or 404 if you have none) quickly and reliably."],
  robots_disallow_all: ["error", "robots.txt blocks Googlebot from the site", "Google can't fetch any page, so nothing new gets indexed and existing pages lose their snippets.", "Remove the Disallow: / rule for Googlebot (or *) unless the site really must stay out of Google."],
  robots_txt_large: ["warning", "robots.txt over 500 KiB", "Google ignores everything after the first 500 KiB of robots.txt.", "Shorten it: group rules with wildcards and remove obsolete lines."],
  robots_blocks_resources: ["warning", "robots.txt blocks CSS or JavaScript the page needs", "Google renders pages like a browser; blocked files can make it see a broken or empty page.", "Allow the site's CSS and JS files in robots.txt."],
  soft_404: ["error", "Missing pages answer 200 (soft 404)", "A page that doesn't exist should return 404/410. A 200 makes every mistyped or deleted URL look like a real, empty page, which wastes crawling and gets flagged as soft 404s.", "Return HTTP 404 (or 410 for removed pages) from the not-found page."],
  host_variant_tls: ["error", "Address variant shows a certificate error", "Visitors who type this version (often www) get a browser security warning, and Google can't follow its redirect.", "Get a certificate that covers this host name (e.g. reissue the SSL to include www), then confirm it 301s to the main address."],
  host_variant_missing: ["warning", "Address variant doesn't load", "People type www (or not) out of habit; if that version has no DNS record they get an error page.", "Add the DNS record (e.g. CNAME www → your domain) and 301 it to the main address."],
  host_variant_redirect: ["warning", "Address variant doesn't 301 to the main address", "http/https and www/non-www versions should all permanently redirect to one address so links and signals land on one site.", "Redirect every variant with a 301 straight to the main address."],
  uncrawlable_links: ["warning", "Links Google can't follow", "Google follows only <a> elements with an href URL (Martin Splitt, 2024; Google link best practices). javascript: links, onclick navigation, <a> without href, role=\"link\" or data-href elements, and #! or #/ hash routes (Google ignores the #fragment; the _escaped_fragment_ scheme was retired) hide the pages behind them. Jump links to #sections and menu toggles aren't counted. With rendering on, the raw and rendered HTML are both checked.", "Use <a href=\"/page.html\"> for every link to a page; for single-page apps, use real paths with the History API instead of # routes."],
  meta_refresh: ["warning", "Meta refresh redirect", "Google treats meta refresh as a redirect but prefers server-side 301s; delays and loops confuse users.", "Replace it with a 301 redirect on the server."],
  nofollow_page: ["warning", "Page tells crawlers not to follow any of its links (meta nofollow)", "Google won't use this page's links to discover or credit the pages they point to.", "Remove nofollow from the robots meta tag unless that's intended."],
  sitemap_blocked: ["error", "Sitemap lists URLs blocked by robots.txt", "The sitemap asks Google to crawl pages robots.txt forbids, so they can't be indexed properly.", "Remove those URLs from the sitemap, or allow them in robots.txt."],
  links_to_redirect: ["notice", "Internal links point at redirecting URLs", "Every redirect is an extra fetch for crawlers and an extra hop for visitors.", "Point the links straight at the final URL."],
  param_trap: ["warning", "Many ?parameter copies of one page", "Crawlers spend their visits on endless variants of the same page instead of real pages.", "Link to the clean URL, give variants a canonical to it, or stop generating crawlable parameter links."],

  // ---------------- Google crawl checks (REQ-046, Google Search Central docs, Oct 2026) ----------------
  head_closed_early: ["warning", "Head closed early: canonical or hreflang ends up in the body", "In the raw HTML an element that isn't allowed in <head> (a div, img, iframe, span, stray text…) comes before the canonical or hreflang links. HTML parsers, Google's included, close the head at that element, so the tags after it land in the body. Google accepts rel=canonical and hreflang only inside a valid <head> (canonical and hreflang docs). A robots meta tag in the body is still honoured by Google (robots meta tag doc, Mar 2026).", "Move the canonical, hreflang and robots tags above the element named in the detail, or move that element into the <body> (often an injected <div>, an <img> or <iframe> tracking pixel, or a stray character). Check with View Source: DevTools shows the repaired DOM, not the source."],
  robots_txt_changed: ["notice", "robots.txt changed since the last audit", "robots.txt controls what every crawler may fetch; an unplanned edit (a CMS or plugin setting, a staging file copied live) can block pages without anyone noticing. Google usually caches robots.txt for up to 24 hours, so a change takes effect within about a day.", "Check that the change in the detail was intended. Search Console's robots.txt report shows the version Google last fetched."],
  robots_disallow_added: ["warning", "New robots.txt rule blocks pages that were indexable", "A Disallow rule added since the last audit stops Googlebot fetching pages that were indexable then, or the whole site. Google can't recrawl blocked pages: their URLs can still show in results but without a description, and updates to them aren't seen (robots.txt introduction).", "If the block wasn't intended, remove or narrow the rule. To keep a page out of Google, leave it crawlable and use noindex instead of Disallow."],
  favicon_issue: ["notice", "Home page favicon problem", "Google shows a site's favicon next to its results only when the home page declares one with <link rel=\"icon\"> (or shortcut icon / apple-touch-icon), Googlebot-Image may crawl the file, and the image is square, at least 8x8 px (over 48x48 recommended), in BMP, GIF, ICO, PNG, JPEG, PPM or TIFF (favicon guidelines). One favicon per host name.", "Add <link rel=\"icon\" href=\"/favicon.ico\"> (or a PNG) to the home page's <head>, serve it with HTTP 200, allow it in robots.txt, and use a square image of 48x48 px or larger (e.g. 96x96 or 192x192). Keep its URL stable."],
  back_button_hijack: ["warning", "Possible back-button hijacking script", "Since 13 April 2026 Google's spam policies (malicious practices) name back-button hijacking: scripts that insert or replace history entries so the back button doesn't return to the previous page. Enforcement began 15 June 2026 with manual actions or automated demotions. Google notes it often comes from an included library or ad platform.", "Open the script named in the detail and remove or disable code that calls history.pushState in a popstate handler, pushes entries in a loop, or redirects when the visitor presses back; for a third-party tag, remove it or ask the vendor. This is a heuristic: confirm by pressing back in a browser."],
  // ---------------- Index signals (REQ-044: Google Search Central docs and videos, Oct 2026) ----------------
  unavailable_after_passed: ["warning", "unavailable_after date has passed", "The page's robots meta tag or X-Robots-Tag says unavailable_after a date before the audit, so Google no longer shows the page in results (robots meta tag doc). Often a leftover from a promotion or event.", "Remove the unavailable_after rule, or set a future date, if the page should stay in Google."],
  unavailable_after_invalid: ["notice", "unavailable_after date can't be read", "Google ignores unavailable_after unless the date is in a widely used format such as RFC 822, RFC 850 or ISO 8601 (robots meta tag doc), so this rule has no effect.", "Write the date in ISO 8601 (e.g. 2027-06-25T15:00:00Z) or remove the rule."],
  robots_other_bot: ["notice", "Robots rules for other crawlers only (information)", "This page has robots rules scoped to a crawler other than Googlebot (e.g. bingbot: noindex). Google ignores rules for other user agents, so they don't affect Google; they do affect that crawler.", "Check each rule is meant for that crawler. To apply one to Google too, use name=\"robots\" (or googlebot) or an unscoped X-Robots-Tag."],
  canonical_conflict: ["warning", "Canonical signals conflict", "Google treats rel=canonical as a strong hint, weighed with other signals. A canonical that is empty, an unfilled template value or contains a #fragment can't be used; one that points to a noindex page, to a URL that canonicalises on elsewhere (a chain or loop), to the home page from pages with their own content, or that differs from the HTTP Link header canonical sends mixed signals, and Google may choose another URL (canonicalization docs; Allan Scott, 2024; John Mueller, Google Search News Nov 2024).", "Point each page's canonical at the final, indexable URL of the version you want shown, as a full absolute URL in the server's HTML; keep the Link header and the HTML tag the same."],
  canonical_form: ["notice", "Canonical is relative or points to another host", "Google supports relative canonical URLs but recommends absolute ones, which avoid mistakes on staging copies and alternative hosts (canonicalization docs). A canonical to another host is a cross-domain canonical: fine for syndicated copies, a mistake when the host is a staging site or the wrong www/non-www version.", "Write the canonical as the full absolute URL on the host you want indexed, e.g. https://example.com/page.html."],
  soft_404_content: ["warning", "Page looks like an error page but answers 200 (soft 404)", "The title or H1 says not found / no results and the page has little text, or its text is identical to the site's own 404 page, yet it returns HTTP 200. Google treats such pages as soft 404s and leaves them out of the index; meanwhile they use up crawling (soft 404 docs; Martin Splitt, 2022). The wording rule is a heuristic.", "Return HTTP 404 or 410 for pages that don't exist; if the page should be indexed, give it real content (e.g. related items on an empty listing)."],
  redirect_to_home: ["warning", "URL redirects to the home page", "A deep URL that redirects to the home page has no real replacement there, so Google may treat the redirect as a soft 404 instead of passing the old URL on (Google redirects and soft 404 guidance).", "Redirect the URL to the closest matching page, or return 404/410 when nothing replaces it; update links and the sitemap."],
  robots_blocked_noindex: ["warning", "noindex on a page robots.txt blocks", "Google can't fetch a URL that robots.txt disallows, so it never sees the noindex on it; the URL can still be indexed from links, without its content (robots.txt introduction; Gary Illyes, 2022).", "To keep the page out of Google, remove the robots.txt rule so Googlebot can read the noindex. Use robots.txt only for what Google shouldn't fetch."],
  robots_blocked_linked: ["notice", "Many internal links to a robots.txt-blocked URL", "Google can index a robots.txt-blocked URL from links without its content and show it with no description (robots.txt introduction). Fine when the URL only needs to stay uncrawled (cart, login).", "If the URL must stay out of Google, allow crawling and add noindex instead; if it should rank, allow crawling. Otherwise no change is needed."],
  sitemap_fetch_error: ["warning", "Sitemap can't be read", "A sitemap named in robots.txt or in a sitemap index returns an error, isn't a sitemap (e.g. an HTML page) or isn't well-formed XML, so Google can't use the URLs in it (Search Console sitemaps report; Daniel Waisberg and John Mueller, 2020).", "Make each listed sitemap return HTTP 200 with valid sitemap XML (escape & as &amp;), a gzip of it, an RSS/Atom feed or a plain list of URLs; remove dead entries from robots.txt and the sitemap index."],
  sitemap_too_large: ["error", "Sitemap over Google's limits, or a nested sitemap index", "Google reads at most 50,000 URLs and 50 MB (uncompressed) per sitemap file, and a sitemap index can't list other sitemap indexes (Google sitemaps docs). A file over the limits can be rejected whole.", "Split large sitemaps into files under 50,000 URLs and 50 MB and list them in one sitemap index; list only sitemaps, not indexes, in an index."],
  raw_vs_rendered: ["warning", "Raw HTML and rendered page disagree (canonical, robots, title, H1, links, structured data or main text)", "Google reads the raw HTML first and renders JavaScript later. With noindex in the raw HTML Google may skip rendering, so JavaScript can't remove it; a canonical that JavaScript changes or removes conflicts with the original HTML (JavaScript SEO basics). Google does pick up titles, links, structured data and text that JavaScript adds once it renders the page (Martin Splitt, 2020; Rendering JavaScript for Google Search, 2024), but that waits for rendering, and crawlers that don't run JavaScript (many AI and social crawlers) never see them. A brand part added to the title is ignored here; menu, header and footer links aren't counted. Checked only when JavaScript rendering is on.", "Put the final canonical and robots meta in the server's HTML and don't change them with JavaScript; never ship noindex in the raw HTML of a page that should be indexed. Server-render or pre-render the title, H1, main content, content links, structured data and hreflang."],

  // ---------------- Rendering and links (REQ-044 build rows 5, 9, 13, 14, 27-33: Google Search Central docs and videos, Oct 2026) ----------------
  render_resource_blocked: ["warning", "Rendering needs files robots.txt blocks", "While rendering this page the browser loaded same-site scripts, styles or data (XHR/fetch) that robots.txt disallows for Googlebot. Google renders pages with the files they load but doesn't fetch disallowed ones, so it can see a broken or incomplete page (Rendering JavaScript for Google Search, 2024; John Mueller: Google needs CSS and JavaScript to see the page). Third-party and analytics files are left out. Checked only when JavaScript rendering is on.", "Allow these files (or their folder) for Googlebot in robots.txt; keep blocking only URLs that aren't needed to show the page."],
  render_js_error: ["notice", "JavaScript error while rendering", "An uncaught JavaScript error stopped a script while the page rendered. Google renders with an up-to-date Chromium: content or links a failed script never adds aren't indexed (JavaScript SEO basics). Errors from third-party scripts rarely affect the content. Checked only when JavaScript rendering is on.", "Open the page with the browser console, fix the error named in the detail (or catch it), and check the rendered HTML in Search Console's URL Inspection."],
  render_js_error_content: ["warning", "JavaScript error and the rendered page has lost its text", "The site's own script threw an uncaught error and the rendered page has under 20% of the raw HTML's main text, or neither has more than 50 words (an app that didn't start). Google indexes what the rendered page shows, so content the failed script should have shown isn't indexed (JavaScript SEO basics). The text comparison is a heuristic.", "Fix the script error named in the detail first; then server-render the main content so it doesn't depend on the script running."],
  broken_internal_resource: ["error", "Broken internal scripts, styles or fonts", "The page loads a same-site script, stylesheet, preload or font file that answers 404 or another error. Google fetches these files to render the page, so a missing file can leave Google with a broken or empty page (Martin Splitt, 2020: removed or renamed asset files break renders); visitors see a broken layout. Files that still refuse after the checker's browser retries (401/403/429) are left out as bot walls.", "Restore the file or update the page to the current file name. When a deploy renames hashed files, keep the old ones available for a while."],
  js_redirect: ["notice", "JavaScript redirect", "After rendering, the page sends the browser to another URL with JavaScript. Google follows JavaScript redirects and treats them like redirects, but only when it renders the page, so a server-side redirect is preferred (John Mueller, 2022; Google redirects docs). Crawlers that don't run JavaScript stay on the old URL. Changes of query string or #hash only (consent and A/B tools) are ignored.", "Use a server-side 301 (permanent) or 302 (temporary) redirect instead, and update links to point at the final URL."],
  links_to_canonicalized: ["notice", "Internal links point at URLs that canonicalise elsewhere", "Google uses internal links as one of the signals for choosing the canonical URL; links to a URL whose rel=canonical names another URL send a signal against your own canonical (Martin Splitt, Canonicalization: SEO Mythbusting, 2020; Allan Scott, 2024). Form pre-fill links (?service=… with a canonical to the clean URL) are left out.", "Link straight to the canonical URL named in the detail."],
  sitemap_non_canonical: ["warning", "Sitemap lists URLs that canonicalise to another URL", "Google treats the sitemap as a canonical signal: it should list only the URLs you want shown in results (canonicalization docs; Martin Splitt, 2020). A sitemap URL whose rel=canonical names another URL, or a ?query version of a clean canonical URL, sends conflicting signals.", "List the canonical URL in the sitemap instead, or change the page's canonical if the sitemap URL is the one you want shown."],
  internal_link_tracking_params: ["notice", "Internal links with tracking parameters", "Every URL with utm_*, gclid, fbclid, msclkid, _ga or similar parameters is a separate URL to Google: internal links with them make duplicate URLs that use up crawling and split canonical signals (Gary Illyes, Crawling smarter, not harder, 2024). Analytics also starts a new campaign session on each click. Filter parameters such as ?color= aren't flagged.", "Link to the clean URL inside the site; keep tracking parameters for links from emails, ads and other sites."],
  url_variant_200: ["notice", "Same page answers 200 at another URL form", "This URL differs from another crawled page only by letter case, a trailing slash or /index.html (or .php), shows the same text, answers 200 and has no canonical to the main form. Google treats each form as a separate URL and has to choose a canonical itself; links and signals split between them (canonicalization docs; Martin Splitt, 2020).", "301-redirect this form to the main URL (or give it a canonical to the main URL) and link only to the main form."],
  generic_anchor_text: ["notice", "Generic link text (\"click here\", \"read more\")", "Google uses anchor text to understand the page a link points to, and asks for descriptive link text; \"click here\", \"read more\" or \"mehr\" say nothing about the target (Google link best practices; Martin Splitt, How to use internal linking for SEO, 2024). Only links in the page's own content are counted, not menus, header or footer; an aria-label or title that names the target exempts the link.", "Rewrite the visible link text to say what the target page is (e.g. \"brake repair prices\" instead of \"click here\"). On repeated cards, put the post title in the link."],
  empty_anchor: ["notice", "Links with no anchor text", "The link has no text, no image alt text and no aria-label, so it tells Google and screen readers nothing about its target. For an image link Google uses the image's alt text as the anchor text (Google link best practices). Only links in the page's own content are counted.", "Add descriptive link text, or alt text to the image inside the link."],
  affiliate_link_unqualified: ["warning", "Affiliate links without rel=\"sponsored\" or \"nofollow\"", "Links that are paid for or earn a commission should carry rel=\"sponsored\" (rel=\"nofollow\" is also accepted); unmarked paid links can count as link spam (Google Search News, Sept 2019; John Mueller, Linking out, 2019; qualify outbound links doc). Detected by affiliate network link formats (Amazon tag=, Awin, CJ, ShareASale, Impact…) and by /go/, /out/ or /recommends/ links that redirect off the site.", "Add rel=\"sponsored\" (or rel=\"nofollow\") to each affiliate link, including cloaked /go/ links."],
  ugc_link_unqualified: ["notice", "Links in comments or reviews without rel=\"ugc\" or \"nofollow\"", "Google recommends rel=\"ugc\" (or nofollow) on links inside user-generated content such as comments, forum posts and reviews, so links visitors post don't count as links the site vouches for (Google Search News, Sept 2019; Sustainable monetized websites, 2021). Links to the site's own host are left out; links staff add in replies may stay followed, so check them by hand.", "Add rel=\"ugc\" to links in comments, forums and reviews (most CMSs and comment plugins have a setting for this)."],
  crawl_trap_links: ["warning", "Internal links into crawl traps (cart actions, session IDs, stacked filters, endless calendars)", "Links that add to cart, carry session IDs or comment-reply parameters, are double-encoded, stack three or more filters, or page a calendar years ahead or back create near-endless URL sets; Google spends its crawling on them instead of real pages (Gary Illyes, Crawling smarter, not harder, 2024). Google retired the URL parameters tool in 2022 and points to robots.txt for this. Links already nofollow or blocked by robots.txt are left out.", "Block the pattern in robots.txt (a suggestion is in the detail), make actions such as add-to-cart a button or form POST instead of a link, and nofollow calendar next/previous links beyond the dates that matter."],
  // ---------------- Structured data (REQ-044 build rows 11, 12, 22, 23, 42-45: Google's structured data docs, Oct 2026) ----------------
  schema_required_missing: ["warning", "Structured data missing properties Google requires", "Google's structured data docs list required properties for each rich-result type: without them the item isn't eligible for that rich result (missing recommended properties only lower its quality). Checked for Product (name; offers, review or aggregateRating; Offer price), LocalBusiness (name, address), BreadcrumbList (at least two ListItems with position, name and item), Event (name, startDate, location with address), Review, AggregateRating (ratingValue; ratingCount or reviewCount), JobPosting and Recipe. Only top-level nodes are checked by type; nested ones only for what Google lists for that slot.", "Add the properties named in the detail with the page's real values, then test the page in Google's Rich Results Test. If the page isn't really that type, remove the markup."],
  schema_recommended_missing: ["notice", "Structured data missing properties Google recommends", "The item can still get its rich result, but Google recommends these properties for a fuller, more accurate result (Article headline, image, datePublished and author.name; LocalBusiness telephone, url, street address and opening hours; Offer availability; Product image and Offer priceCurrency, which merchant listings require). Organization: name, and a logo given as an absolute image URL.", "Add the recommended properties the page can truthfully fill; skip any that don't apply."],
  schema_value_not_visible: ["warning", "Marked-up value not shown on the page", "Google's structured data guidelines require markup to describe content readers can see; a price, availability, rating count or phone number that differs from the page (or an unfilled template value such as {{price}}) can cost the rich result or earn a manual action, and price mismatches hurt merchant listings. Detected: the Offer price (within 1%), availability against sold-out or in-stock wording (one product only), ratingCount/reviewCount and the LocalBusiness telephone digits missing from the page text. These are heuristics; AggregateOffer price ranges aren't checked.", "Make the markup and the visible page agree: fix the template that fills the markup, or show the value on the page. If the value is added by JavaScript, check the rendered page."],
  site_name_markup: ["notice", "Site name markup missing or inconsistent", "Google picks the site name shown in results automatically; WebSite structured data (name, url) on the home page is the most important way to state a preference, and Google also reads og:site_name, the title and headings there, so they should use the same name (site names doc). alternateName offers fallbacks. Google supports site names per domain or subdomain only, so WebSite markup aimed at a subdirectory is ignored.", "Add WebSite JSON-LD with name and url (and alternateName if useful) to the home page, and use that same name in og:site_name and the brand part of page titles. Remove WebSite markup that names a subdirectory as its url."],
  local_nap_missing: ["notice", "Local business details incomplete on the home page", "For a local business, Google uses the name, address, phone and opening hours on the site, LocalBusiness markup (address required; telephone and openingHoursSpecification recommended) and the Business Profile; they should agree and be visible (Search for Beginners: Top 5 things to consider for your website, 2020; local business structured data docs). Service-area businesses without a street address pass the address part. Hours are compared only when both the markup and the page text can be read; that comparison is a heuristic.", "Show the phone, street address and opening hours as text on the home page, mark them up in the LocalBusiness JSON-LD, and keep both identical to the Google Business Profile."],
  schema_retired_type: ["notice", "Structured data for a retired rich result (information)", "Google no longer shows a rich result for this markup (HowTo since Sept 2023, sitelinks search box since Nov 2024, FAQ since 7 May 2026, and the features phased out in 2025: special announcement, fact check, course info, learning video, vehicle listing, estimated salary; online-event properties were removed from the Event docs on 5 June 2025; data-vocabulary.org since 2021). The markup is harmless and doesn't affect ranking. Book actions and the Course list carousel are still supported. The list is in src/retired-schema.json.", "Nothing is required. Keep the markup only if other consumers use it; otherwise remove it to simplify the page."],
  schema_date_issue: ["notice", "Structured data dates problem", "Google's Article and Video docs recommend a time zone with any time; without one Google assumes Googlebot's time zone. dateModified before datePublished, a date after the audit date, or a markup date that differs from the single date shown on the page make the byline date unreliable (publication dates doc: keep visible and structured dates consistent). Date-only values are fine; event start dates are left out (Google reads them in the event's own time zone).", "Write dates as ISO 8601 with an offset (2026-10-27T09:00:00+11:00), keep dateModified on or after datePublished, and make the markup match the date shown on the page."],
  schema_conflicting_entities: ["notice", "Conflicting entities in the page's structured data", "Two top-level business nodes (Organization or LocalBusiness) on the page give different names, phone numbers or street addresses, or two Product nodes for the same product give different prices, so Google can't tell which is right (Martin Splitt, Structured data for beginners, 2024). Often two plugins each add their own markup. Nodes with the same @id count as one; nodes linked with parentOrganization, subOrganization or department aren't compared. Legal-form words (Pty Ltd, Inc, LLC) are ignored in names.", "Keep one node per real entity: remove the duplicate plugin's markup, or give both the same @id and the same values. Link genuinely separate entities (a branch and its parent) with parentOrganization."],
  merchant_policy_missing: ["notice", "No return or shipping policy markup on a site that sells products", "Products with prices are marked up on 3 or more pages, but no crawled page has return policy markup (MerchantReturnPolicy / hasMerchantReturnPolicy) or shipping markup (shippingDetails / hasShippingService). Google recommends both for merchant listings, preferably as one site-wide policy under Organization, with Offer-level overrides only where needed (Organization, merchant listing, return policy and shipping policy docs).", "Add hasMerchantReturnPolicy and hasShippingService to the Organization markup on the home page (or hasMerchantReturnPolicy / shippingDetails on each Offer), describing the real policy."],
  // ---------------- Site probes and site rules (REQ-044 build rows 16-18, 21, 34, 35, 46, 50-53: Google Search Central docs and videos, Oct 2026) ----------------
  internal_search_indexable: ["warning", "Internal search results pages can be indexed", "Google advises keeping internal search result pages out of its index: they are auto-generated, add little for someone arriving from Google, and every query is a new URL to crawl (John Mueller, \"Should you block your Search result pages?\", 2026). This search URL answers 200, has no noindex, isn't blocked by robots.txt and isn't just the home page.", "Add <meta name=\"robots\" content=\"noindex\"> to search result pages, or disallow the search path in robots.txt (not both: a robots.txt block hides the noindex). Don't link to search URLs from the site's own pages."],
  internal_search_echoed: ["error", "Search results page repeats the search words in its title or H1", "Anyone can create an indexable page on this site with any words in its title or H1, just by linking to a search URL. Spammers use such pages to get their text shown under other sites' names, and Google advises keeping search result pages out of the index (John Mueller, 2026).", "Add noindex to search result pages (or block the search path in robots.txt) and stop echoing the raw query into the <title> and H1."],
  mobile_desktop_parity: ["warning", "Smartphone crawler gets less than desktop", "Google indexes the version of a page its smartphone crawler gets (mobile-first indexing; John Mueller, Google Search News July 2024: all sites are crawled with the smartphone crawler). Text, links, structured data or meta tags that only the desktop HTML has are missing from Google's index. Raw HTML is compared, so content hidden with CSS on phones isn't counted as missing. The 70% thresholds are this tool's heuristic.", "Serve the same main content, internal links, structured data, title, description, canonical, robots and hreflang to phones and desktops (responsive design does this). With a separate m-dot site, keep the two in parity."],
  googlebot_ua_diff: ["warning", "Googlebot gets a different page than visitors", "Showing Googlebot something different from what visitors get is cloaking under Google's spam policies, and a bot challenge or block page means Google indexes that page instead of the content (Martin Splitt and John Mueller, \"How to read the Indexing Report\", 2026). This tool isn't Google: a firewall that checks Googlebot's IP addresses blocks a request that only claims to be Googlebot, which is fine.", "Run the URL Inspection live test in Search Console. If Google's own crawler also gets a different page, remove the user-agent rules (CDN, firewall, plugin or server config) that change the response for Googlebot."],
  search_referrer_redirect: ["error", "Visitors from Google are redirected to another site", "The page sends people who arrive from Google (Referer: google.com) to another host, but not people who come directly. That is a sneaky redirect under Google's spam policies and a common sign of a hacked site (Google, \"Security issues explained\", 2020).", "Treat it as a hack until proven otherwise: check .htaccess, server config, plugins and recently changed files for referrer-based redirects, clean them up, change passwords, and check Search Console's Security issues report."],
  robots_txt_syntax: ["notice", "robots.txt lines Google ignores or can't read", "Google reads only user-agent, allow, disallow and sitemap lines. Other fields (crawl-delay, noindex, host, clean-param…) are ignored, a line it can't read as \"field: value\" is skipped, a rule path must start with / or *, Sitemap needs a full URL, and a robots.txt that is HTML may give no rules at all. Google's parser accepts a few misspellings (\"dissallow\"), other crawlers may not (Google robots.txt docs; Gary Illyes, 2019 and 2021).", "Fix or remove the listed lines. To slow Googlebot down, answer 503 or 429 for a while instead of crawl-delay (Google crawl rate docs), and use a noindex robots meta tag or X-Robots-Tag instead of noindex in robots.txt."],
  robots_group_override: ["notice", "Googlebot ignores the robots.txt rules written for all crawlers", "Google follows only the most specific group that matches it: once robots.txt has a \"User-agent: Googlebot\" group, Googlebot ignores every rule in the \"User-agent: *\" group (Google robots.txt docs). Disallow rules that are only in the * group don't apply to Google. Fine if deliberate.", "Repeat the * group's Disallow rules in the Googlebot group, or remove the Googlebot group if it isn't needed."],
  staging_host_exposed: ["warning", "Staging or preview copy of the site is public", "A copy of the site on a staging, test or preview host answers without a login, has no noindex and isn't blocked by robots.txt, so Google can crawl and index it as a duplicate of the live site. Google's Gary Illyes recommends keeping staging sites behind authentication (Search Off the Record, \"Staging and launching a site\", 2023).", "Put the staging host behind a password (HTTP authentication) or an IP allowlist. noindex or a robots.txt block also keep it out of the index, but are easy to copy to the live site by mistake at launch."],
  login_page_indexable: ["notice", "Indexable login page with almost no content", "The page has a password field and under 150 words. When a login page shows up in search, searchers who aren't customers find nothing useful; John Mueller (\"Optimizing login-page content for Google Search\", 2025) suggests describing the product or service on it, or keeping it out of search.", "Add a short description of what the account is for and how to get one, or add noindex if the page shouldn't appear in search."],
  login_redirect_hub: ["notice", "Many URLs redirect to the login page", "Five or more crawled URLs redirect to the same login page, so Google sees that login page in place of every one of them and can't index what they are about (John Mueller, \"Optimizing login-page content for Google Search\", 2025).", "Make pages that should rank viewable without logging in. For private pages, answer 401/403 or add noindex instead of redirecting, and don't link to them from public pages."],
  email_in_url: ["warning", "Email address in a URL", "Email addresses in URLs end up in server logs, analytics, referrer headers sent to other sites, and search results. That leaks personal data; Google Analytics' own policies forbid sending email addresses to it.", "Pass email addresses in a POST body, never in the URL. Change the forms or links that put them there, and redirect or remove the indexed URLs."],
  sitemap_lastmod_inaccurate: ["notice", "Sitemap lastmod doesn't follow content changes", "Google uses <lastmod> only when it is consistently and verifiably accurate (Google sitemap docs; Daniel Waisberg and John Mueller, \"Sitemaps in Search Console\", 2020). Compared with the previous audit, these URLs' lastmod moved while their main text stayed the same, or their main text changed while lastmod didn't. Menu and footer changes don't count when the page has a <main> element.", "Set lastmod from the date the page's main content last changed, not from build or deploy time, and update it whenever the content changes."],
  no_conditional_get: ["notice", "No conditional requests (304 Not Modified)", "Google's crawlers support HTTP caching with ETag / If-None-Match and Last-Modified / If-Modified-Since; a 304 answer saves the server and Googlebot a full download, and Gary Illyes noted few sites answer 304 (\"Crawling smarter, not harder\", 2024; Google crawler docs). Information about crawl efficiency: pages built on every request often can't answer 304, which is fine.", "Let the server or CDN send an ETag or Last-Modified header and answer 304 when the request's If-None-Match / If-Modified-Since still matches (most static file servers and caching plugins do this)."],
  no_compression: ["warning", "Text files sent without compression", "Google's crawlers support gzip, deflate and Brotli (br) content encodings (Google crawler docs). An uncompressed HTML, CSS or JavaScript file takes several times longer to download, for visitors and for crawlers.", "Turn on gzip or Brotli compression for text types in the server or CDN (e.g. mod_deflate / mod_brotli, or the host's compression setting)."],
  exposed_secret_files: ["error", "Secret files are publicly readable", "A file that should never be public (an environment file with keys and passwords, or Git repository data) answers 200 with matching content. Attackers scan for these files. Google's Search Central team lists \"no source code or API keys published\" among the checks before a site goes live (\"Vibe Coding - yay or nay?\", 2026). The file's content is not stored by this tool.", "Block access to dot-files on the server (a deny rule for paths such as /.env and /.git/), move the file outside the web root, and change every password and key it contained."],
  source_map_exposed: ["notice", "JavaScript source maps are public (information)", "The site's script names a .map file that anyone can download, which publishes the original source code. Not a Google ranking issue; information for the developer.", "Don't deploy .map files to the live site, or restrict access to them, unless publishing the source is intended."],
  tls_cert_expiring: ["warning", "HTTPS certificate expires soon", "When the certificate expires, browsers show a security error and Googlebot can't fetch the HTTPS pages (Google, \"HTTPS\", 2020; Gary Illyes, \"Debugging the Internet\", 2025: TLS failures stop crawling). Certificates that renew automatically are flagged at 10 days left instead of 21, because renewal normally happens in the last 30 days.", "Renew the certificate, or check why automatic renewal (e.g. AutoSSL, Let's Encrypt) hasn't run: DNS, a blocked validation path, or a failed renewal job."],
  tls_cert_critical: ["error", "HTTPS certificate expires within 7 days or has expired", "An expired certificate makes browsers block the site with a security warning and stops Googlebot fetching HTTPS pages (Google, \"HTTPS\", 2020; Gary Illyes, \"Debugging the Internet\", 2025).", "Renew the certificate now and check that the renewal job works."],
  locale_redirect: ["warning", "Home page redirects by browser language", "The home page sends visitors to a different URL depending on their Accept-Language. Google's multilingual docs advise against automatic language redirects: they stop people (and Googlebot, which usually crawls without a language preference) from reaching other versions, and John Mueller calls forced redirects his pet peeve (Google Search News Nov 2024).", "Show every visitor the URL they asked for, offer the other language with a banner or switcher, and link the versions with hreflang."],
  // ---------------- hreflang, spam, images, titles, video, CTA (REQ-044 build rows 7, 10, 26, 36-40, 54, 55, Oct 2026) ----------------
  hreflang_no_return: ["warning", "hreflang alternates don't link back", "Google's localized-versions docs: \"If page X links to page Y, page Y must link back to page X\"; otherwise the annotations may be ignored or not interpreted correctly. A crawled alternate named here has no hreflang link back to this page. Alternates that weren't crawled aren't checked.", "Add the same full set of hreflang links (including a self-reference) to every language version, so each version lists all the others."],
  hreflang_bad_target: ["warning", "hreflang points to a URL that can't be indexed", "An hreflang target that redirects, answers an error, is noindex, is blocked by robots.txt or canonicalises to another URL can't take part in the language cluster; Google expects each hreflang URL to be the version's own indexable, canonical URL (localized-versions docs; Gary Illyes, \"Internationalization & hreflang\", SOTR 2024).", "Point each hreflang link at the final, indexable URL of that language version (the URL its own canonical names)."],
  hreflang_xdefault_conflict: ["notice", "Language versions name different x-default pages", "x-default names the fallback page for searchers whose language matches no version (localized-versions docs). Pages of one hreflang cluster that name different x-default URLs give Google conflicting fallbacks; every version should carry the same set of annotations.", "Use one x-default URL (often the language selector or the main version) in the hreflang set of every page in the cluster."],
  keyword_stuffing: ["warning", "Possible keyword stuffing", "Google's spam policies define keyword stuffing as filling a page with keywords or numbers to manipulate rankings, often \"in a list or group, unnaturally, or out of context\", with the examples \"Blocks of text that list cities and regions that a web page is trying to rank for\" and \"Repeating the same words or phrases so often that it sounds unnatural\". Flagged (heuristics; Google publishes no numbers): a block of 15 or more short comma, pipe or line-break separated items, mostly capitalised names or repeating one word; or a 2–4 word phrase used 10 or more times that makes up 4% or more of the main text. Menus, tables, address blocks, breadcrumbs and lists whose items have their own links are left out; brand names are ignored.", "Read the passage aloud: if it's a list of places or a phrase repeated for search engines, cut it to what helps readers (e.g. \"We serve the south-eastern suburbs\" plus a link to a service-area page) and write naturally. A genuine list readers need is fine."],
  hacked_spam_signals: ["error", "Signs of hacked or injected spam", "Google's spam policies (hacked content) describe code, page and content injection: pages or hidden links and text added without permission, often pharma, casino or adult spam, or Japanese keyword pages (Daniel Waisberg and Aurora Morales, \"Security issues explained\", 2020). Spam words in this page's title, H1, link text or hidden text (display:none, off-screen) that never appear on the home page, Japanese titles on a site in another language, or spam words in the text of a page that is new since the last audit. Words on the home page, brand names and the project's allowed spam words are ignored.", "Open the page: if you didn't add this content, treat the site as hacked: check Search Console's Security issues report, remove the injected pages and code, update the CMS and plugins, change passwords, then request a review. If the words are genuine, add them to the project's allowed spam words."],
  new_external_script: ["notice", "New third-party script on most pages since the last audit", "A script host that loads on half or more of the pages now and on none in the previous audit. Usually a tag someone added on purpose (analytics, chat, ads); injected script tags are also the most common form of code injection on hacked sites (Google spam policies, hacked content).", "Check the host named in the detail was added on purpose. If nobody knows it, remove it and check the site for other injected code."],
  lcp_image_lazy: ["warning", "Above-the-fold image is lazy-loaded", "The first content image on the page, above the first H2, has loading=\"lazy\". The browser then waits for layout before fetching it, which delays the largest image on the first screen and hurts Largest Contentful Paint, a Core Web Vital (Martin Splitt, \"Lazy loading demystified\", 2025). Logos, icons, the site header and images under 100 px are skipped. Heuristic: Lighthouse's LCP element is the measured answer.", "Remove loading=\"lazy\" from the first large image (keep it on images further down), and consider fetchpriority=\"high\" on it."],
  img_src_placeholder: ["notice", "Images whose real URL is only in data-src", "The <img> has no src, a data: URI or a placeholder file in src, and the real image URL only in data-src / data-srcset, with no <noscript> fallback. Google Images indexes the URL in the src (or srcset) attribute; a lazy-loading script must swap it in for Google to see the image (images best practices; lazy-loading guidance).", "Use native loading=\"lazy\" with the real URL in src, or make sure the script sets src when rendered and add a <noscript><img src=\"real.jpg\"></noscript> fallback."],
  img_alt_generic: ["notice", "Generic image alt text or file names", "Google uses alt text, with computer vision and the page text, to understand an image, and calls file names \"very light clues\": IMG00023.JPG says nothing (images best practices; John Mueller, \"Let's talk image SEO\", SOTR 2022). Flagged: alt text that is the file name, a word such as \"image\" or \"photo\", starts with \"image of\" / \"picture of\", or the same alt on 5 or more different images; and camera or screenshot file names. alt=\"\" (decorative) is fine.", "Describe what each meaningful image shows, in the context of the page, without stuffing keywords; give new image files short descriptive names (e.g. black-kitten.jpg)."],
  images_blocked_by_robots: ["notice", "Images blocked by robots.txt", "robots.txt disallows these image URLs (or VideoObject thumbnails) for Google's image crawler, so they can't appear in Google Images and a blocked video thumbnail makes the video ineligible for video results (images best practices; video best practices: the thumbnail must be accessible to Googlebot). One line per folder. Fine for icons or sprites blocked on purpose.", "Allow the folder for Googlebot-Image (or Googlebot) in robots.txt if these images should be found in search."],
  dup_h1: ["notice", "Same H1 on several pages", "Google builds title links from the <title>, headings and other prominent text (title links doc; Gary Illyes, \"Anatomy of a Search Result\", 2024). The same H1 on pages that aren't language versions of each other makes them harder to tell apart for readers and in results. Pages whose titles are also identical (dup_title) and ?page= series are left out.", "Give each page an H1 that says what is specific to it."],
  title_quality: ["notice", "Keyword-list, repeated-brand or boilerplate title", "Google's title links doc: \"there's no reason to have the same words or phrases appear multiple times\" (keyword stuffing can make results look spammy), avoid \"repeated or boilerplate text in <title> elements\", and brand titles concisely. Flagged (heuristics): the brand twice or more, 4 or more segments split by | , or dashes, one word 3 or more times, or a leading/trailing part over 60% of the title shared by 10 or more pages. Google may rewrite such title links.", "Write each title as a short description of that page, with the brand once at most (usually at the end)."],
  video_not_main: ["notice", "Video may not count as the page's main content", "To be eligible for video features Google needs a dedicated watch page whose main purpose is to show one video; where the video is complementary to the text, the page can still show as a text result (video best practices). This page has VideoObject markup but its first video comes after half of the main text, or it embeds 3 or more videos (heuristics: Google's systems decide).", "If you want video results, give the video its own watch page (video near the top, title and description about the video) and point the VideoObject there; otherwise nothing is required."],
  video_thumbnail_unreachable: ["warning", "Video thumbnail or file can't be fetched", "Google's video best practices: a video needs a valid thumbnail at a stable URL that Googlebot can fetch, and Google must be able to fetch the video file for previews and key moments. This VideoObject's thumbnailUrl doesn't answer 200, or its contentUrl doesn't answer 200 with a video file type. Up to 20 URLs are checked per audit.", "Fix the thumbnailUrl / contentUrl in the VideoObject to stable URLs that answer 200 (an image and a video file); avoid expiring CDN links."],
  // ---------------- Bot walls and slow-down answers (REQ-055 group 1, Oct 2026) ----------------
  bot_wall_blocked: ["warning", "Pages answer the crawler with a bot challenge", "The site's own pages answered this tool's crawler with a bot challenge or firewall block page (e.g. Cloudflare \"Just a moment...\", an Akamai \"Access Denied\" with a reference number, a captcha). If the CDN or firewall challenges crawlers it doesn't know, Google's crawlers can be refused too unless they are allowlisted; a challenged page can't be crawled or indexed, and Search Console reports it as blocked (403) or as a server error. The detail says whether a fallback (curl or a real browser) got the page anyway.", "In the CDN or firewall, allowlist verified Googlebot (most CDNs have a \"verified bots\" setting) and this tool's user agent for your own audits, or lower the bot-protection level for crawlers. Then confirm with Search Console's URL Inspection live test that Google gets the real page."],
  fetched_via_fallback: ["notice", "Pages that loaded only through a fallback (information)", "These pages refused the crawler's normal request (401, 403, 503, no answer or a challenge page) and were read through curl or a real browser instead. Their content was checked as usual; their response time and JavaScript rendering weren't, because the fallback's timing isn't the server's answer to a crawler.", "Usually the same fix as bot_wall_blocked: allowlist crawlers in the CDN or firewall. If the page also loads for Search Console's URL Inspection, Google can read it."],
  crawl_rate_limited: ["notice", "The site asked the crawler to slow down (429/503)", "During the audit the server answered 429 Too Many Requests, or 503 with a Retry-After header. The crawler waited as long as asked (up to 60 s), retried each page once and lowered its parallel requests for the rest of the audit. Google reduces its crawl rate on 429 and 503 answers too, so steady slow-down answers can slow the crawling and indexing of new pages (Google crawl rate docs).", "If the limit is unintended, raise it for crawlers in the server, CDN or security plugin, or check the server has enough capacity. For this tool, lower Parallel requests in the project settings (2–3 on small shared hosting)."],
  cta_below_fold: ["notice", "Call to action below the first phone screen (conversion, not a Google ranking issue)", "On a 412×823 phone screen the first phone link, email link or call-to-action button of this home or money page starts below the first screen, and there is no sticky call bar. Visitors who are ready to act have to scroll to find how. A conversion and UX notice, not a Google ranking factor (Rio Ichikawa, \"A discussion of UX for SEO\", Search Off the Record 2024, anecdotal). Checked on up to 6 pages when a browser is available.", "Put the main action (call, book, get a quote) in the first screen on phones, e.g. a button under the H1 or a sticky call bar."],
};

/** Checks shown under the Crawlability tab: can search engines reach and fetch the pages? */
export const CRAWL = new Set(["http_4xx", "http_5xx", "broken_internal_link", "redirect_chain", "temporary_redirect", "permanent_redirect", "very_slow", "http_page",
  "blocked_by_robots", "no_robots_txt", "no_sitemap", "sitemap_not_in_robots", "sitemap_bad_url", "noindex_in_sitemap", "sitemap_orphan", "not_in_sitemap", "deep_page",
  "single_inlink", "nofollow_internal", "url_too_long", "robots_txt_error", "robots_disallow_all", "robots_txt_large", "robots_blocks_resources", "soft_404",
  "host_variant_tls", "host_variant_missing", "host_variant_redirect", "uncrawlable_links", "meta_refresh", "nofollow_page", "sitemap_blocked", "links_to_redirect", "param_trap",
  "head_closed_early", "robots_txt_changed", "robots_disallow_added", "raw_vs_rendered", "unavailable_after_passed", "canonical_conflict", "soft_404_content", "redirect_to_home",
  "internal_search_indexable", "internal_search_echoed", "mobile_desktop_parity", "googlebot_ua_diff", "robots_txt_syntax", "robots_group_override", "staging_host_exposed",
  "login_redirect_hub", "sitemap_lastmod_inaccurate", "no_conditional_get", "no_compression", "tls_cert_expiring", "tls_cert_critical", "locale_redirect",
  "robots_blocked_noindex", "robots_blocked_linked", "sitemap_fetch_error", "sitemap_too_large", "render_resource_blocked", "render_js_error", "render_js_error_content",
  "broken_internal_resource", "js_redirect", "sitemap_non_canonical", "internal_link_tracking_params", "url_variant_200", "crawl_trap_links",
  "bot_wall_blocked", "fetched_via_fallback", "crawl_rate_limited"]);

export const SEVERITY = (id) => CHECKS[id][0];

const W = (p) => p.data || {};

// Headlines that are about a past year on purpose: history, archives, past events, "since/established/founded".
const ON_PURPOSE = /\b(history|historic(?:al)?|archives?|since|established|est\.|founded|anniversary|events?|recap|in review|annual report|timeline|then and now|copyright)\b|©/i;
const UNIT_AFTER = /^\s?(?:\+|%|km|kg|mm|cm|cc|ml|mg|mah|rpm|w|kw|hp|mb|gb|ft|sq|words|people|users|members|calories)\b|^[+%]/i;

/** First year from 2000 to currentYear-1 in a title or H1, or null. Not flagged: headlines about history, archives,
 *  events or "since/established/founded <year>"; ranges that reach the current year ("2025/26", "2021–present");
 *  numbers that are prices, quantities or units ("$2000", "2,019", "2000 km"); and years glued to a model code
 *  with a hyphen ("XR-2020"). Model years written as words ("2019 Corolla") can't be told apart and are flagged. */
export function pastYear(text, currentYear) {
  if (!text || ON_PURPOSE.test(text)) return null;
  for (const m of text.matchAll(/\b(20\d{2})\b/g)) {
    const y = +m[1], before = text.slice(0, m.index), after = text.slice(m.index + 4);
    if (y >= currentYear || /[$€£¥#]\s*$|[\d.,]$|[a-z]-$/i.test(before) || UNIT_AFTER.test(after) || /^[.,]\d/.test(after)) continue;
    const range = after.match(/^\s*[-–—/]\s*(\d{4}|\d{2}|present|now|today)\b/i);
    if (range && (!/\d/.test(range[1]) || (range[1].length === 2 ? 2000 + +range[1] : +range[1]) >= currentYear)) continue;
    return y;
  }
  return null;
}

/** Rules that need only the page itself. Returns [[checkId, detail], ...]. */
export function pageIssues(p, ctx) {
  const out = [];
  const d = W(p);
  const add = (id, detail = "") => out.push([id, detail]);
  const isHtml = (p.content_type || "").includes("html");
  // Fetch ladder (fetch-ladder.mjs): a page still behind a bot wall is bot_wall_blocked, not a missing page or a
  // server error; a page read through curl or the browser has no server response time of its own.
  const direct = !d.fetchedVia || d.fetchedVia === "fetch" || d.fetchedVia === "retry";
  if (d.botWall) {
    const w = d.botWall, tried = d.fallbackTried?.length ? `still refused after ${d.fallbackTried.join(" and ")}` : "no fallback tried (setting or robots.txt)";
    add("bot_wall_blocked", `${w.vendor === "unknown" ? "" : w.vendor + " "}${w.kind} page (HTTP ${w.status}); ${direct ? tried : `the page loaded via ${d.fetchedVia}`}`);
  }
  if (!direct) add("fetched_via_fallback", `loaded via ${d.fetchedVia} after the normal request got ${d.directStatus ? "HTTP " + d.directStatus : "no answer"}`);
  const walled = d.botWall && p.status >= 400; // reported as bot_wall_blocked
  if (!walled && p.status >= 500) add("http_5xx", `HTTP ${p.status}`);
  else if (!walled && p.status >= 400) add("http_4xx", `HTTP ${p.status}`);
  if (d.redirect) {
    if (d.redirect.hops > 1 || d.redirect.loop) add("redirect_chain", d.redirect.loop ? "redirect loop" : `${d.redirect.hops} hops → ${d.redirect.to}`);
    if ([302, 303, 307].includes(d.redirect.firstStatus)) add("temporary_redirect", `${d.redirect.firstStatus} → ${d.redirect.to}`);
    else add("permanent_redirect", `${d.redirect.firstStatus} → ${d.redirect.to}`);
  }
  if (p.url.startsWith("http://") && ctx.siteIsHttps) add("http_page");
  if (direct && p.response_ms > 5000) add("very_slow", `${p.response_ms} ms`);
  else if (direct && p.response_ms > 1500) add("slow_page", `${p.response_ms} ms`);
  if (d.blockedByRobots) add("blocked_by_robots");
  if (p.url.length > 115) add("url_too_long", `${p.url.length} chars`);
  if (p.status === 200 && d.unavailableAfter) { // header or meta, any content type (PDFs use the header)
    const ua = d.unavailableAfter, today = ctx.auditDate || new Date().toISOString().slice(0, 10);
    if (!ua.at) add("unavailable_after_invalid", `"${ua.raw}"`);
    else if (ua.at.slice(0, 10) < today) add("unavailable_after_passed", `unavailable_after ${ua.raw} (before the audit date ${today})`);
  }
  if (p.status === 200 && d.robotsOtherBots?.length) add("robots_other_bot", d.robotsOtherBots.join("; "));
  // A ?query variant whose canonical is its own clean URL is set up correctly; its content is checked on that URL.
  if (d.variantOf) {
    if (p.in_sitemap && p.status === 200) add("sitemap_non_canonical", `?query URL in the sitemap; its canonical is the clean URL ${d.variantOf}`);
    return out;
  }
  if (p.status !== 200 || !isHtml) return out;

  if (p.bytes > 2 * 1024 * 1024) add("large_html", `${Math.ceil(p.bytes / 1024)} KB uncompressed; Googlebot reads only the first 2,048 KB`);
  if (!p.indexable && d.noindex) add("noindex_page", d.noindexSource || "");
  if (!p.title) add("missing_title");
  else if (p.title.length > 65) add("title_too_long", `${p.title.length} chars`);
  else if (p.title.length < 20) add("title_too_short", `${p.title.length} chars`);
  if (!p.description) add("missing_description");
  else if (p.description.length < 70 || p.description.length > 170) add("desc_length", `${p.description.length} chars`);
  if (!d.h1Count) add("missing_h1");
  else if (d.h1Count > 1) add("multiple_h1", `${d.h1Count} H1s`);
  if (p.title && p.h1 && p.title.trim().toLowerCase() === p.h1.trim().toLowerCase()) add("dup_title_h1");
  if (p.words < 200 && p.indexable) add("low_word_count", `${p.words} words`);
  if (p.text_ratio < 10 && p.indexable && !(d.formShare >= 0.4)) add("low_text_ratio", `${p.text_ratio}%`);
  if (d.imgNoAlt) add("img_missing_alt", `${d.imgNoAlt} image(s)`);
  if (d.lcpLazy) add("lcp_image_lazy", `loading="lazy" on the first content image: ${d.lcpLazy}`);
  if (d.imgPlaceholder) add("img_src_placeholder", `${d.imgPlaceholder} image(s), e.g. ${d.imgPlaceholderExample}`);
  if (d.imgAltGeneric || d.imgGenericName) add("img_alt_generic", [d.imgAltGeneric && `${d.imgAltGeneric} generic alt text(s), e.g. ${d.imgAltGenericExample}`,
    d.imgGenericName && `${d.imgGenericName} camera/screenshot file name(s), e.g. ${d.imgGenericNameExample}`].filter(Boolean).join("; "));
  if (!d.viewport) add("missing_viewport");
  if (!d.lang) add("missing_lang");
  if (d.canonicals > 1) add("canonical_multiple", `${d.canonicals} tags`);
  if (!d.canonicals && p.indexable) add("missing_canonical");
  if (p.canonical && p.canonical !== p.url && p.canonical !== p.final_url) add("canonical_elsewhere", p.canonical);
  if (d.canonicalProblem) add("canonical_conflict", d.canonicalProblem);
  else if (d.canonicalHeader && p.canonical && d.canonicalHeader !== p.canonical) add("canonical_conflict", `HTTP Link header canonical ${d.canonicalHeader}, HTML canonical ${p.canonical}`);
  if (d.canonicalForm) add("canonical_form", d.canonicalForm);
  if (d.jsonldInvalid) add("invalid_jsonld", `${d.jsonldInvalid} block(s)`);
  if (d.faqHidden) add("schema_faq_hidden", d.faqHidden);
  if (d.crumbHidden) add("schema_breadcrumb_hidden");
  if (d.selfReview) add("schema_self_review");
  if (p.indexable) for (const [id, det] of schemaPageIssues(d, ctx)) add(id, det);
  if (!d.jsonld && !d.microdata && p.indexable) add("missing_jsonld");
  if (!d.og && p.indexable) add("missing_og");
  if (d.mixed) add("mixed_content", `${d.mixed} resource(s), e.g. ${d.mixedExample}`);
  if (d.hreflangBad) add("hreflang_issue", d.hreflangBad);
  if (p.outlinks > 300) add("many_links", `${p.outlinks} links`);
  if (d.nofollowInternal) add("nofollow_internal", `${d.nofollowInternal} link(s)`);
  if (d.jsLinks) add("uncrawlable_links", `${d.jsLinks} link(s)${d.jsLinkExample ? `, e.g. ${d.jsLinkExample}` : ""}`);
  if (d.metaRefresh) add("meta_refresh", d.metaRefresh);
  if (d.nofollowMeta) add("nofollow_page", d.nofollowMeta === "X-Robots-Tag" ? "via X-Robots-Tag header" : "");
  if (d.headClosedEarly) { const h = d.headClosedEarly; add("head_closed_early", `${h.element} on line ${h.line} closes the head; after it: ${h.tags.join(", ")}${h.robots ? ", robots meta (Google still honours that one)" : ""}`); }
  if (d.rawVsRendered) add("raw_vs_rendered", d.rawVsRendered);
  if (d.renderBlocked?.length) add("render_resource_blocked", `${d.renderBlocked.length} file(s) disallowed for Googlebot, e.g. ${d.renderBlocked.slice(0, 2).join(", ")}`);
  if (d.renderErrors?.length) {
    const e = d.renderErrors.find((x) => x.firstParty) || d.renderErrors[0];
    const det = `${d.renderErrors.length} error(s), e.g. "${e.message}"${e.source ? ` in a script from ${e.source}` : ""}${e.firstParty ? "" : " (third-party)"}`;
    if (d.renderErrorContent) add("render_js_error_content", `${det}; ${d.renderErrorContent}`);
    else add("render_js_error", det);
  }
  if (d.jsRedirect) add("js_redirect", d.jsRedirect.loop ? `JavaScript redirect loop: ${d.jsRedirect.chain.join(" → ")}` : `to ${d.jsRedirect.to}`);
  if (d.genericAnchors) add("generic_anchor_text", `${d.genericAnchors} link(s): ${d.genericAnchorDetail}`);
  if (d.emptyAnchors) add("empty_anchor", `${d.emptyAnchors} link(s), e.g. → ${d.emptyAnchorExample}`);
  if (d.ugcUnqualified) add("ugc_link_unqualified", `${d.ugcUnqualified} link(s), e.g. ${d.ugcExample}`);
  if (d.backButton) add("back_button_hijack", `possible, in ${d.backButton}`);
  if (d.passwordField && p.indexable && p.words < 150) add("login_page_indexable", `password field and ${p.words} words`);
  if (d.externalLinks > 2 && d.externalLinks === d.externalNofollow) add("external_nofollow_all");
  if (p.depth > 3) add("deep_page", `depth ${p.depth}`);
  if (p.indexable && ctx.sitemapLoaded && !p.in_sitemap) add("not_in_sitemap");
  // Not indexable only because the canonical names another URL: that's a canonical conflict, not a noindex.
  if (!p.indexable && p.in_sitemap) {
    if (!d.noindex && p.canonical && p.canonical !== p.url && p.canonical !== p.final_url) add("sitemap_non_canonical", `canonical is ${p.canonical}`);
    else add("noindex_in_sitemap");
  }
  if (p.indexable) contentIssues(p, d, ctx, add);
  return out;
}

/** Content age, structure and video rules for an indexable page. The audit date is ctx.auditDate (yyyy-mm-dd, set by
 *  the crawler when the crawl ends), or today when it is missing. */
function contentIssues(p, d, ctx, add) {
  const today = ctx.auditDate || new Date().toISOString().slice(0, 10);
  const types = d.schemaTypes || [];
  const listing = (d.childLinks || 0) >= 5 || types.some((t) => /^(Blog|CollectionPage|ItemList)$/.test(t));
  const newest = [d.dateModified, d.datePublished].filter(Boolean).sort().at(-1);
  const yearBefore = `${+today.slice(0, 4) - 1}${today.slice(4)}`; // same day one year earlier (ISO strings compare by date)
  if (newest && !listing && newest < yearBefore && isArticle(p)) {
    const months = (+today.slice(0, 4) - +newest.slice(0, 4)) * 12 + (+today.slice(5, 7) - +newest.slice(5, 7));
    add("content_stale", `newest date on the page: ${newest} (${months} months before the audit)`);
  }
  // News reports and event pages are about their year by nature.
  if (!types.some((t) => /^(NewsArticle|Event)$|Event$/.test(t))) {
    const year = +today.slice(0, 4);
    const t = pastYear(p.title, year), h = t ? null : pastYear(p.h1, year);
    if (t || h) add("title_past_year", t ? `title mentions ${t}: "${p.title.slice(0, 80)}"` : `H1 mentions ${h}: "${p.h1.slice(0, 80)}"`);
  }
  if (d.headingSkips) add("heading_skip", `${d.headingSkips} skip(s), e.g. ${d.headingSkipExample}`);
  if (d.headingsBeforeH1) add("heading_before_h1", `${d.headingsBeforeH1} heading(s) before the H1`);
  if (p.words >= 1500 && d.h2Count >= 4 && !(d.jumpLinks >= 2)) add("long_no_toc", `${p.words} words, ${d.h2Count} H2s, ${d.jumpLinks || 0} jump link(s) to headings`);
  if (d.longParas) add("long_paragraphs", `${d.longParas} paragraph(s), longest ${d.longParaMax} words`);
  if (d.videos && !d.videoObjects) add("video_no_schema", `${d.videos} video embed(s), no VideoObject`);
  const notMain = videoNotMain(d, p.words);
  if (notMain) add("video_not_main", notMain);
  if (d.videoObjectsIncomplete) add("video_schema_incomplete", `${d.videoObjectsIncomplete} VideoObject(s); missing ${d.videoObjectMissing}`);
}

/** Health score: share of crawled pages free of errors, warnings counting half (documented in the UI). */
export function healthScore(pageCount, pagesWithErrors, pagesWithWarningsOnly) {
  if (!pageCount) return 0;
  return Math.max(0, Math.round(100 * (1 - (pagesWithErrors + 0.5 * pagesWithWarningsOnly) / pageCount)));
}
